package app.mindgarden.personal;

import android.app.*;import android.content.*;import android.content.res.*;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.util.*;import android.view.*;import android.webkit.*;import android.widget.*;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;import android.util.Base64;

public class MainActivity extends Activity {
 private static final String ORIGIN="https://appassets.androidplatform.net/", HOME=ORIGIN+"assets/index.html";
 private static final int TREE=11,RESTORE=12,EXPORT=13,FILES=14;
 private WebView web;private android.widget.FrameLayout root;private android.content.SharedPreferences prefs;
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();private ScheduledFuture<?> pendingBackup;
 private VoiceCapture voice;private GitHubSync github;private final ExecutorService syncWorker=Executors.newSingleThreadExecutor();
 private final Object vaultLock=new Object();private ValueCallback<Uri[]> fileCallback;private volatile String backupError="",currentTheme="";private boolean destroyed=false;
 private File vault(){return new File(getFilesDir(),"vault");}private File records(){return new File(vault(),"records.json");}
 private File attachment(String id)throws IOException{if(!BackupArchive.validId(id))throw new IOException("文件编号无效");return new File(vault(),"files/"+id);}
 private String read(File f)throws IOException{return new String(java.nio.file.Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
 private void message(String value){runOnUiThread(()->{if(!destroyed)Toast.makeText(this,value,Toast.LENGTH_LONG).show();});}
 private void js(String value){runOnUiThread(()->{if(!destroyed&&web!=null)web.evaluateJavascript(value,null);});}
 private void notifyStatus(){js("window.updatePhoneStatus&&window.updatePhoneStatus()");}
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("garden",MODE_PRIVATE);new File(vault(),"files").mkdirs();root=new android.widget.FrameLayout(this);root.setBackgroundColor(Color.rgb(23,58,50));setContentView(root);web=new WebView(this);root.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));
   if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()),ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));return insets;});}else root.setFitsSystemWindows(true);
   getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
   WebSettings s=web.getSettings();s.setTextZoom(100);s.setLayoutAlgorithm(WebSettings.LayoutAlgorithm.NORMAL);s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);s.setMediaPlaybackRequiresUserGesture(true);s.setDefaultTextEncodingName("UTF-8");
   voice=new VoiceCapture(this,this::js);web.addJavascriptInterface(voice,"GardenCaptureNative");github=new GitHubSync(this);web.addJavascriptInterface(new PhoneBridge(),"GardenPhone");
   web.setWebViewClient(new WebViewClient(){
    @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();if("appassets.androidplatform.net".equals(u.getHost())&&"/assets/GardenSans.otf".equals(u.getPath()))try{return new WebResourceResponse("font/otf",null,getAssets().open("GardenSans.otf"));}catch(IOException ignored){}if("appassets.androidplatform.net".equals(u.getHost())&&"/assets/index.html".equals(u.getPath()))try{Map<String,String> headers=new HashMap<>();headers.put("Content-Security-Policy","default-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self' blob:; object-src 'none'; base-uri 'none'; frame-src 'none'");return new WebResourceResponse("text/html","UTF-8",200,"OK",headers,getAssets().open("index.html"));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream("无法打开应用".getBytes(StandardCharsets.UTF_8)));}return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
    @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(u.toString().equals(HOME))return false;if(request.hasGesture()&&("https".equals(u.getScheme())||"http".equals(u.getScheme())))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){message("没有找到可以打开链接的应用");}return true;}
   });
   web.setWebChromeClient(new WebChromeClient(){
    @Override public boolean onJsAlert(WebView v,String url,String text,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(text).setPositiveButton("知道了",(d,w)->r.confirm()).setOnCancelListener(d->r.cancel()).show();return true;}
    @Override public boolean onJsConfirm(WebView v,String url,String text,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(text).setPositiveButton("确定",(d,w)->r.confirm()).setNegativeButton("取消",(d,w)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}
    @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(i,FILES);}catch(Exception e){fileCallback.onReceiveValue(null);fileCallback=null;message("暂时无法选择文件");}return true;}
   });if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->onBackPressed());web.loadUrl(HOME);
 }
 private void validAction(JSONObject a)throws Exception{if(!BackupArchive.validId(a.getString("id"))||!(a.opt("title") instanceof String))throw new IOException("行动内容不完整");}
 private JSONObject validate(String json)throws Exception{JSONObject d=new JSONObject(json);if(!(d.opt("goals") instanceof JSONArray)||!(d.opt("ideas") instanceof JSONArray)||!(d.opt("evidence") instanceof JSONArray))throw new IOException("备份内容不完整");JSONArray goals=d.getJSONArray("goals");for(int i=0;i<goals.length();i++){JSONObject g=goals.getJSONObject(i);validAction(g);JSONArray skills=g.getJSONArray("skills");for(int j=0;j<skills.length();j++){JSONObject s=skills.getJSONObject(j);validAction(s);JSONArray acts=s.getJSONArray("actions");for(int k=0;k<acts.length();k++)validAction(acts.getJSONObject(k));}}JSONArray ideas=d.getJSONArray("ideas");for(int i=0;i<ideas.length();i++){JSONObject idea=ideas.getJSONObject(i);if(!BackupArchive.validId(idea.getString("id"))||!(idea.opt("title") instanceof String))throw new IOException("灵感内容不完整");JSONArray actions=idea.optJSONArray("actions");if(actions!=null)for(int j=0;j<actions.length();j++)validAction(actions.getJSONObject(j));}return d;}
 private List<String> fileIds(JSONObject d)throws Exception{List<String> ids=new ArrayList<>();JSONArray ideas=d.getJSONArray("ideas");for(int i=0;i<ideas.length();i++){JSONArray files=ideas.getJSONObject(i).optJSONArray("files");if(files==null)continue;for(int j=0;j<files.length();j++){String id=files.getJSONObject(j).getString("id");if(!BackupArchive.validId(id))throw new IOException("文件编号无效");ids.add(id);}}return ids;}
 private void writeRecords(String value)throws Exception{JSONObject data=validate(value);Set<String> ids=new HashSet<>(fileIds(data));for(String id:ids)if(!attachment(id).isFile())throw new IOException("文件尚未保存，请稍后重试");AtomicFile file=new AtomicFile(records());FileOutputStream stream=null;try{stream=file.startWrite();stream.write(value.getBytes(StandardCharsets.UTF_8));file.finishWrite(stream);}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}File[] existing=new File(vault(),"files").listFiles();if(existing!=null)for(File f:existing)if(BackupArchive.validId(f.getName())&&!ids.contains(f.getName()))f.delete();prefs.edit().putLong("localSaved",System.currentTimeMillis()).apply();}
 private void scheduleBackup(boolean urgent){if(pendingBackup!=null)pendingBackup.cancel(false);if(prefs.getString("folder","").isEmpty())return;pendingBackup=worker.schedule(()->{try{automaticBackup();backupError="";}catch(Exception e){backupError="备份文件夹暂时不可用，请重新选择";}notifyStatus();},urgent?0:3,TimeUnit.SECONDS);}
 private void automaticBackup()throws Exception{if(!records().isFile())return;Uri tree=Uri.parse(prefs.getString("folder",""));Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));String stamp=new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss-SSS",Locale.ROOT).format(new Date());Uri out=DocumentsContract.createDocument(getContentResolver(),parent,"application/zip","心之林-"+stamp+".zip");if(out==null)throw new IOException();try{synchronized(vaultLock){JSONObject data=validate(read(records()));OutputStream stream=getContentResolver().openOutputStream(out,"w");if(stream==null)throw new IOException();BackupArchive.write(vault(),fileIds(data),stream);}}catch(Exception e){try{DocumentsContract.deleteDocument(getContentResolver(),out);}catch(Exception ignored){}throw e;}
   JSONArray old;try{old=new JSONArray(prefs.getString("createdBackups","[]"));}catch(Exception e){old=new JSONArray();}JSONObject item=new JSONObject();item.put("uri",out.toString());item.put("day",new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date()));old.put(item);Set<String> days=new HashSet<>();List<JSONObject> retained=new ArrayList<>();for(int i=old.length()-1;i>=0;i--){JSONObject entry=old.optJSONObject(i);if(entry==null){entry=new JSONObject();entry.put("uri",old.optString(i));entry.put("day","");}String day=entry.optString("day");boolean daily=!day.isEmpty()&&!days.contains(day)&&days.size()<7;if(daily)days.add(day);if(i>=old.length()-3||daily)retained.add(entry);else try{DocumentsContract.deleteDocument(getContentResolver(),Uri.parse(entry.getString("uri")));}catch(Exception ignored){}}Collections.reverse(retained);prefs.edit().putString("createdBackups",new JSONArray(retained).toString()).putLong("backupSaved",System.currentTimeMillis()).apply();
 }
 private void pickFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,TREE);}
 private void createManual(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"心之林-"+new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date())+".zip");startActivityForResult(i,EXPORT);}
 private void restorePicker(){new AlertDialog.Builder(this).setTitle("恢复手机备份").setMessage("恢复会替换当前内容。替换前，会在手机内暂存当前版本。旧网页版的 JSON 备份，请使用“导入旧版备份”。").setNegativeButton("取消",null).setPositiveButton("选择备份",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,RESTORE);}).show();}
 private void deleteTree(File f){if(f==null)return;File[] children=f.listFiles();if(children!=null)for(File c:children)deleteTree(c);f.delete();}
 private void restore(Uri uri){worker.execute(()->{File stage=new File(getFilesDir(),"restore-"+System.nanoTime()),old=new File(getFilesDir(),"previous-vault");try{InputStream source=getContentResolver().openInputStream(uri);if(source==null)throw new IOException();try(InputStream in=source){BackupArchive.extract(in,stage);}JSONObject restored=validate(read(new File(stage,"records.json")));for(String id:fileIds(restored))if(!new File(stage,"files/"+id).isFile())throw new IOException("备份中的文件不完整");synchronized(vaultLock){if(pendingBackup!=null)pendingBackup.cancel(false);if(records().isFile())try(OutputStream out=new FileOutputStream(new File(getFilesDir(),"恢复前的内容.zip"))){BackupArchive.write(vault(),fileIds(validate(read(records()))),out);}deleteTree(old);if(vault().exists()&&!vault().renameTo(old))throw new IOException("手机暂时无法恢复，请重试");if(!stage.renameTo(vault())){old.renameTo(vault());throw new IOException("恢复未完成，原有内容已保留");}prefs.edit().putLong("epoch",prefs.getLong("epoch",1)+1).putBoolean("restoring",true).apply();deleteTree(old);}runOnUiThread(()->{web.reload();message("正在恢复内容和文件…");});}catch(Exception e){deleteTree(stage);message("没有恢复成功："+e.getMessage());}});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(voice!=null&&voice.onActivityResult(request,result,data))return;if(request==FILES){if(fileCallback!=null){List<Uri> selected=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)selected.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)selected.add(data.getData());}fileCallback.onReceiveValue(selected.isEmpty()?null:selected.toArray(new Uri[0]));fileCallback=null;}return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==TREE){try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));prefs.edit().putString("folder",uri.toString()).putString("createdBackups","[]").apply();backupError="";js("window.phoneFolderChosen&&window.phoneFolderChosen()");message("已选好文件夹，之后会自动备份");}catch(Exception e){message("未能记住这个文件夹，请重新选择");}}else if(request==RESTORE)restore(uri);else if(request==EXPORT)worker.execute(()->{try{synchronized(vaultLock){if(!records().isFile())throw new IOException("请稍等内容保存完成");OutputStream out=getContentResolver().openOutputStream(uri,"w");if(out==null)throw new IOException();BackupArchive.write(vault(),fileIds(validate(read(records()))),out);}message("备份已保存");}catch(Exception e){message("没有导出成功："+e.getMessage());}});}
 public final class PhoneBridge {
   @JavascriptInterface public void githubCall(String request){syncWorker.execute(()->{JSONObject reply=new JSONObject();try{JSONObject value=new JSONObject(request);reply.put("id",value.getLong("id"));JSONObject payload=value.getJSONObject("payload");if("recover".equals(payload.optString("action"))){File source=github.safety(payload.optString("side"));if(!source.isFile())throw new IOException("没有找到同步副本");runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("找回内容").setMessage("找回同步前保留的这份内容？当前内容会先留一份副本，恢复后的改动也会参与同步。").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->restore(Uri.fromFile(source))).show());reply.put("result",true);}else reply.put("result",github.call(payload));}catch(Exception e){try{reply.put("error",e instanceof IOException?e.getMessage():"同步暂未完成，请稍后重试");}catch(Exception ignored){}}js("window.syncNativeReply&&window.syncNativeReply("+reply.toString()+")");});}
   @JavascriptInterface public String getRecords(){try{synchronized(vaultLock){return records().isFile()?read(records()):"";}}catch(Exception e){return "";}}
   @JavascriptInterface public boolean hasRecords(){return records().isFile();}
   @JavascriptInterface public boolean isRestoring(){return prefs.getBoolean("restoring",false);}
   @JavascriptInterface public long getEpoch(){return prefs.getLong("epoch",1);}
   @JavascriptInterface public void restoreFinished(long epoch){if(epoch==getEpoch())prefs.edit().putBoolean("restoring",false).apply();}
   @JavascriptInterface public boolean hasAttachment(String id,long size){try{return attachment(id).isFile()&&attachment(id).length()==size;}catch(Exception e){return false;}}
   @JavascriptInterface public String writeChunk(String id,long offset,String encoded,boolean last,long epoch){try{File target=attachment(id),part=new File(target.getPath()+".part");if(encoded.length()>800000)throw new IOException();byte[] bytes=Base64.decode(encoded,Base64.NO_WRAP);synchronized(vaultLock){if(epoch!=getEpoch()||prefs.getBoolean("restoring",false))return "正在恢复，请稍后重试";try(RandomAccessFile out=new RandomAccessFile(part,"rw")){if(offset==0)out.setLength(0);if(out.length()!=offset)throw new IOException();out.seek(offset);out.write(bytes);if(last)out.getFD().sync();}if(last){if(target.exists()&&!target.delete())throw new IOException();if(!part.renameTo(target))throw new IOException();}}return "ok";}catch(Exception e){return "文件保存未完成，请重试";}}
   @JavascriptInterface public String readChunk(String id,long offset){try(RandomAccessFile in=new RandomAccessFile(attachment(id),"r")){in.seek(offset);byte[] bytes=new byte[524288];int n=in.read(bytes);return n<0?"":Base64.encodeToString(Arrays.copyOf(bytes,n),Base64.NO_WRAP);}catch(Exception e){return "";}}
   @JavascriptInterface public String saveRecords(String json,long epoch){try{synchronized(vaultLock){if(epoch!=getEpoch()||prefs.getBoolean("restoring",false))return "正在恢复，请稍后重试";writeRecords(json);}scheduleBackup(false);notifyStatus();return "ok";}catch(Exception e){return "手机保存未完成，请重试";}}
   @JavascriptInterface public String status(){JSONObject result=new JSONObject();try{result.put("folder",!prefs.getString("folder","").isEmpty());result.put("previous",new File(getFilesDir(),"恢复前的内容.zip").isFile());result.put("localSaved",prefs.getLong("localSaved",0));result.put("backupSaved",prefs.getLong("backupSaved",0));result.put("error",backupError);}catch(Exception ignored){}return result.toString();}
   @JavascriptInterface public void chooseFolder(){runOnUiThread(()->pickFolder());}
   @JavascriptInterface public void restoreBackup(){runOnUiThread(()->restorePicker());}
   @JavascriptInterface public void restorePrevious(){runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("撤回上次恢复").setMessage("回到上次恢复之前保留的内容？").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->restore(Uri.fromFile(new File(getFilesDir(),"恢复前的内容.zip")))).show());}
   @JavascriptInterface public void exportBackup(){runOnUiThread(()->createManual());}
   @JavascriptInterface public void backupNow(){scheduleBackup(true);}
   @JavascriptInterface public void openAttachment(String id){runOnUiThread(()->{try{if(!attachment(id).isFile())throw new IOException();Uri uri=Uri.parse("content://"+getPackageName()+".files/"+id);startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,getContentResolver().getType(uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){message("没有找到可以打开这个文件的应用");}});}
   @JavascriptInterface public void setTheme(String theme){if(theme.equals(currentTheme))return;currentTheme=theme;runOnUiThread(()->{boolean day=theme.equals("day");int color=Color.parseColor(day?"#eff4ea":"#173a32");root.setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);if(Build.VERSION.SDK_INT>=30){WindowInsetsController c=getWindow().getInsetsController();if(c!=null)c.setSystemBarsAppearance(day?WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS:0,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}else getWindow().getDecorView().setSystemUiVisibility(day?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);});}
 }
 @Override public void onBackPressed(){web.evaluateJavascript("window.phoneBack?window.phoneBack():false",value->{if(!"true".equals(value))moveTaskToBack(true);});}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(voice!=null)voice.onPermission(request,grants);}
 @Override protected void onPause(){if(voice!=null)voice.pause();if(web!=null)web.evaluateJavascript("window.flushPhoneSave&&window.flushPhoneSave()",null);super.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)js("window.updatePhoneStatus&&window.updatePhoneStatus();window.gardenSyncNow&&window.gardenSyncNow()");}
 @Override protected void onDestroy(){destroyed=true;if(voice!=null)voice.close();if(fileCallback!=null)fileCallback.onReceiveValue(null);if(web!=null){web.removeJavascriptInterface("GardenPhone");web.destroy();}worker.shutdown();syncWorker.shutdownNow();super.onDestroy();}
}
